var textForPages =["\u041d\u043e\u0432\u043e\u0441\u0442\u043d\u043e\u0439 \u0434\u0430\u0439\u0434\u0436\u0435\u0441\u0442 31 \u043e\u043a\u0442\u044f\u0431\u0440\u044f \u2014 7 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a01 08\u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438\u00a0\u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u000d\u000a\u0410\u0444\u0440\u0438\u043a\u0430\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d \u0437\u0430\u043a\u043b\u044e\u0447\u0438\u043b \u0438\u043d\u0432\u0435\u0441\u0442\u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f \u043d\u0430 $17 \u043c\u043b\u0440\u0434 \u000d\u000a\u043d\u0430\u00a0\u0444\u043e\u0440\u0443\u043c\u0435 Gateway Gulf\u000d\u000a\u0421\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u044b \u043d\u0430 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0445 \u0443\u0441\u043b\u0443\u0433, IT, \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438, \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0438 \u0438 \u0442\u0443\u0440\u0438\u0437\u043c\u0430.\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b \u0431\u043e\u043b\u0435\u0435 60 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u043e\u043d\u043d\u044b\u0445 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0439 \u000d\u000a\u043d\u0430 \u0441\u0443\u043c\u043c\u0443 $17 \u043c\u043b\u0440\u0434 \u0432 \u0445\u043e\u0434\u0435 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0444\u043e\u0440\u0443\u043c\u0430 \u000d\u000aGateway Gulf 2025, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043f\u0440\u043e\u0448\u0435\u043b \u043d\u0430 \u0442\u0435\u043a\u0443\u0449\u0435\u0439 \u043d\u0435\u0434\u0435\u043b\u0435 \u000d\u000a\u0432\u00a0\u041c\u0430\u043d\u0430\u043c\u0435. \u041e\u0431 \u044d\u0442\u043e\u043c \u0423\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u000d\u000a\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044f \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430, \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0442\u043e\u0440 \u000d\u000a\u043c\u0435\u0440\u043e\u043f\u0440\u0438\u044f\u0442\u0438\u044f.\u000a\u000d\u000a\u0427\u0435\u0442\u044b\u0440\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0438 \u0441\u0442\u0430\u0442\u0443\u0441 \u00ab\u0437\u043e\u043b\u043e\u0442\u043e\u0439 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438\u00bb, \u000d\u000a\u043f\u0440\u0435\u0434\u0443\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u044e\u0449\u0438\u0439 \u043d\u0430\u043b\u043e\u0433\u043e\u0432\u044b\u0435 \u043b\u044c\u0433\u043e\u0442\u044b \u0438 \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442\u043d\u043e\u0435 \u000d\u000a\u0432\u044b\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u0443\u0447\u0430\u0441\u0442\u043a\u043e\u0432. \u0412 \u0440\u0430\u043c\u043a\u0430\u0445 \u043e\u0434\u043d\u043e\u0433\u043e \u000d\u000a\u0438\u0437\u00a0\u0442\u0430\u043a\u0438\u0445 \u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432 \u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0442\u0435\u043b\u0435\u043a\u043e\u043c-\u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440 \u000d\u000aBatelco \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u0442 \u0446\u0435\u043d\u0442\u0440 \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u0434\u0430\u043d\u043d\u044b\u0445 \u043f\u0440\u0438 \u0443\u0447\u0430\u0441\u0442\u0438\u0438 \u000d\u000aOracle.\u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u043e\u000d\u000aAluminium Bahrain \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b\u0430 \u0441 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 Shandong \u000d\u000aInnovation Group \u0438 \u0438\u043d\u0432\u0435\u0441\u0442\u0444\u043e\u043d\u0434\u043e\u043c BlueFive Capital \u000d\u000a\u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u043e \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0438 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u044b\u0445 \u0446\u0435\u043f\u043e\u0447\u0435\u043a \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0438 \u0443\u043a\u0440\u0435\u043f\u043b\u0435\u043d\u0438\u044f \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438 \u043c\u0435\u0436\u0434\u0443 \u0410\u0437\u0438\u0435\u0439 \u000d\u000a\u0438\u00a0\u0441\u0442\u0440\u0430\u043d\u0430\u043c\u0438 \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430.\u000a\u000d\u000a\u041f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u043c\u0438\u043d\u0444\u0438\u043d\u0430 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430, \u0432\u043e II \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435 2025 \u0433\u043e\u0434\u0430 \u000d\u000a\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 \u0441\u0442\u0440\u0430\u043d\u044b \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043d\u0430 2,5% \u0432 \u0433\u043e\u0434\u043e\u0432\u043e\u043c \u0432\u044b\u0440\u0430\u0436\u0435\u043d\u0438\u0438 \u000d\u000a\u0437\u0430 \u0441\u0447\u0435\u0442 \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u044f \u043d\u0435\u0441\u044b\u0440\u044c\u0435\u0432\u043e\u0433\u043e \u0441\u0435\u043a\u0442\u043e\u0440\u0430 \u043d\u0430 3,5%. \u041f\u0440\u0438\u0442\u043e\u043a \u000d\u000a\u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u044b\u0445 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u0432\u044b\u0440\u043e\u0441 \u043d\u0430 5,4%, \u0434\u043e\u0441\u0442\u0438\u0433\u043d\u0443\u0432 \u2028\u000d\u000a$46,4 \u043c\u043b\u0440\u0434.\u000d\u000a#\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438\u000d\u000aArcapita \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u0443\u0435\u0442 $1 \u043c\u043b\u0440\u0434 \u0432 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0438 \u2028\u000d\u000a\u0438 \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0443 \u0421\u0428\u0410 \u0438 \u0412\u0435\u043b\u0438\u043a\u043e\u0431\u0440\u0438\u0442\u0430\u043d\u0438\u0438\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u043c\u0438 \u043e\u0431\u044a\u0435\u043a\u0442\u0430\u043c\u0438 \u043d\u0435\u0434\u0432\u0438\u0436\u0438\u043c\u043e\u0441\u0442\u0438 \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c\u044e $3 \u043c\u043b\u0440\u0434 \u043f\u043e \u0432\u0441\u0435\u043c\u0443 \u043c\u0438\u0440\u0443. \u0418\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u000d\u000a\u043f\u043e\u0439\u0434\u0443\u0442 \u043d\u0430 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u0445 \u0441\u043a\u043b\u0430\u0434\u0441\u043a\u0438\u0445 \u043f\u043e\u043c\u0435\u0449\u0435\u043d\u0438\u0439 \u0438 \u0434\u0430\u0442\u0430-\u0446\u0435\u043d\u0442\u0440\u043e\u0432.\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0430\u044f \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u043e\u043d\u043d\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Arcapita Group \u000d\u000a \u0431\u043e\u043b\u0435\u0435 $1 \u043c\u043b\u0440\u0434 \u0432 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u000d\u000a\u0438\u00a0\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u043d\u0430 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u0421\u0428\u0410 \u000d\u000a\u0438\u00a0\u0412\u0435\u043b\u0438\u043a\u043e\u0431\u0440\u0438\u0442\u0430\u043d\u0438\u0438 \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u0433\u043e \u0433\u043e\u0434\u0430.\u000a\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0443\u0434\u0435\u043b\u0438\u0442 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0435 \u0432\u043d\u0438\u043c\u0430\u043d\u0438\u0435 \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0435\u043d\u0438\u044e \u000d\u000a\u0438\u00a0\u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u044e \u0434\u0430\u0442\u0430-\u0446\u0435\u043d\u0442\u0440\u043e\u0432 \u0432 \u0421\u0428\u0410, \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u044e\u0449\u0438\u0445 \u000d\u000a\u0432\u043b\u043e\u0436\u0438\u0442\u000d\u000a\u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u0438\u0441\u043a\u0443\u0441\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u0438\u043d\u0442\u0435\u043b\u043b\u0435\u043a\u0442\u0430 \u0438 \u043e\u0431\u043b\u0430\u0447\u043d\u044b\u0445 \u000d\u000a\u0440\u0435\u0448\u0435\u043d\u0438\u0439. \u0420\u0430\u043d\u0435\u0435 \u0432 \u044d\u0442\u043e\u043c \u0433\u043e\u0434\u0443 Arcapita \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430 \u043e \u043f\u043b\u0430\u043d\u0430\u0445 \u000d\u000a\u0441\u043e\u0437\u0434\u0430\u0442\u044c \u0438\u043d\u0432\u0435\u0441\u0442\u0444\u043e\u043d\u0434 \u0432 \u0441\u0444\u0435\u0440\u0435 \u043d\u0435\u0434\u0432\u0438\u0436\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0431\u0449\u0435\u0439 \u000d\u000a\u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c\u044e \u043e\u043a\u043e\u043b\u043e $1 \u043c\u043b\u0440\u0434 \u0434\u043b\u044f \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0441\u0432\u043e\u0438\u043c\u0438 \u000d\u000a\u0430\u043a\u0442\u0438\u0432\u0430\u043c\u0438 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435.","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438\u00a0\u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 31 \u043e\u043a\u0442\u044f\u0431\u0440\u044f \u2014 7 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u0430\u0432\u0438\u0430\u0446\u0438\u044f\u000d\u000a\u041c\u0430\u043b\u0430\u0439\u0437\u0438\u0439\u0441\u043a\u0438\u0439 \u043f\u0435\u0440\u0435\u0432\u043e\u0437\u0447\u0438\u043a AirAsia \u0441\u043e\u0437\u0434\u0430\u0441\u0442 \u0430\u0432\u0438\u0430\u0445\u0430\u0431 \u000d\u000a\u0432\u00a0\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0435\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u0435\u0442 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u0443\u044e \u0430\u0432\u0438\u0430\u0446\u0438\u043e\u043d\u043d\u0443\u044e \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443. \u0421\u0435\u0439\u0447\u0430\u0441 \u0430\u044d\u0440\u043e\u043f\u043e\u0440\u0442 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430 \u043e\u0431\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u0435\u0442 \u043e\u043a\u043e\u043b\u043e \u000d\u000a70 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0439. \u0420\u0430\u043d\u0435\u0435 \u0432\u043b\u0430\u0441\u0442\u0438 \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0438 \u043e \u043f\u043b\u0430\u043d\u0430\u0445 \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u0442\u044c \u043d\u043e\u0432\u044b\u0439 \u0430\u044d\u0440\u043e\u043f\u043e\u0440\u0442 \u043d\u0430 \u0441\u0435\u0432\u0435\u0440\u043e-\u0437\u0430\u043f\u0430\u0434\u0435 \u0441\u0442\u0440\u0430\u043d\u044b.\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0430\u0437\u0438\u0430\u0442\u0441\u043a\u0438\u0439 \u043b\u043e\u0443\u043a\u043e\u0441\u0442\u0435\u0440 AirAsia \u0437\u0430\u043a\u043b\u044e\u0447\u0438\u043b \u000d\u000a\u0441\u00a0\u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e\u043c \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u043f\u0440\u0435\u0434\u0432\u0430\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u000d\u000a\u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u043e \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0438 \u0441\u0432\u043e\u0435\u0439 \u0440\u0435\u0433\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u0431\u0430\u0437\u044b \u000d\u000a\u043d\u0430\u00a0\u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430. \u041e\u0431 \u044d\u0442\u043e\u043c \u000d\u000a\u0441\u043e\u043e\u0441\u043d\u043e\u0432\u0430\u0442\u0435\u043b\u044c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0422\u043e\u043d\u0438 \u0424\u0435\u0440\u043d\u0430\u043d\u0434\u0435\u0441 \u043d\u0430 \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u0444\u043e\u0440\u0443\u043c\u0435 \u0432 \u041c\u0430\u043d\u0430\u043c\u0435.\u000a\u000d\u000a\u0418\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0445\u043e\u043b\u0434\u0438\u043d\u0433 Capital A, \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u000d\u000a\u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 \u043f\u0435\u0440\u0435\u0432\u043e\u0437\u0447\u0438\u043a, \u0437\u0430\u043a\u043b\u044e\u0447\u0438\u043b \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0435 \u000d\u000a\u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u043e \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u0438\u044f\u0445 \u0441 \u043c\u0438\u043d\u0442\u0440\u0430\u043d\u0441\u043e\u043c \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430. \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b \u000d\u000a\u0421\u0443\u043c\u043c\u0430 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u0432 \u043f\u0440\u043e\u0435\u043a\u0442 \u0438 \u0434\u0440\u0443\u0433\u0438\u0435 \u0434\u0435\u0442\u0430\u043b\u0438 \u000d\u000a\u043d\u0435\u00a0\u0441\u043e\u043e\u0431\u0449\u0430\u044e\u0442\u0441\u044f.\u000a\u000d\u000aAirAsia \u043d\u0430\u0440\u0430\u0449\u0438\u0432\u0430\u0435\u0442 \u043f\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435. \u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u044c \u0441\u0432\u043e\u0439 \u043f\u0430\u0440\u043a \u0441 255 \u2028\u000d\u000a\u0434\u043e 600 \u0441\u0430\u043c\u043e\u043b\u0435\u0442\u043e\u0432 \u0438 \u0440\u0430\u0441\u0448\u0438\u0440\u0438\u0442\u044c \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u043d\u0443\u044e \u0441\u0435\u0442\u044c \u2028\u000d\u000a\u0441 143 \u0434\u043e 175 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0439 \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 10 \u043b\u0435\u0442. \u0420\u0430\u043d\u0435\u0435 \u000d\u000a\u0441\u0443\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u0439 \u0444\u043e\u043d\u0434 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u043b \u000d\u000a\u0432\u00a0\u043f\u0435\u0440\u0435\u0432\u043e\u0437\u0447\u0438\u043a\u0430 $100 \u043c\u043b\u043d.\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438\u000d\u000aDP World \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u0443\u0435\u0442 $5 \u043c\u043b\u0440\u0434 \u0432 \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u000d\u000a\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u0418\u043d\u0434\u0438\u0438\u000d\u000a\u041d\u043e\u0432\u044b\u0435 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0434\u043e\u043f\u043e\u043b\u043d\u044f\u0442 \u0443\u0436\u0435 \u0432\u043b\u043e\u0436\u0435\u043d\u043d\u044b\u0435 $3 \u043c\u043b\u0440\u0434, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u0440\u0435\u0434\u043d\u0430\u0437\u043d\u0430\u0447\u0430\u043b\u0438\u0441\u044c \u0434\u043b\u044f \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044f \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u000d\u000a\u0438\u00a0\u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u044f \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0439 DP World. \u0418\u043d\u0434\u0438\u0439\u0441\u043a\u0430\u044f \u0441\u0435\u0442\u044c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u043e\u0445\u0432\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u0431\u043e\u043b\u0435\u0435 200 \u043e\u0431\u044a\u0435\u043a\u0442\u043e\u0432 \u0438 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u0435\u0442 \u000d\u000a\u0441\u0432\u044b\u0448\u0435 24 \u0442\u044b\u0441. \u0440\u0430\u0431\u043e\u0447\u0438\u0445 \u043c\u0435\u0441\u0442.\u000d\u000a\u042d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u0430\u044f DP World \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430 \u043e \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u0438\u0438 \u0432\u043b\u043e\u0436\u0438\u0442\u044c \u000d\u000a\u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 $5 \u043c\u043b\u0440\u0434 \u0432 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u000d\u000a\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u043d\u0430 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u0418\u043d\u0434\u0438\u0438. \u041e\u0431 \u044d\u0442\u043e\u043c \u000d\u000a \u0432 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0438 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430.\u000a\u000d\u000aDP World \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b\u0430 \u043f\u044f\u0442\u044c \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0439 \u0441 \u0438\u043d\u0434\u0438\u0439\u0441\u043a\u0438\u043c\u0438 \u000d\u000aSagarmala Finance Corporation, Cochin Shipyard Limited \u000d\u000a\u0438\u00a0Drydocks World. \u0412 \u0447\u0430\u0441\u0442\u043d\u043e\u0441\u0442\u0438, \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u000d\u000a\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f\u000d\u000a\u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u043b\u0441\u044f \u0441 Sagarmala Finance \u043e \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0438 \u000d\u000a\u043f\u0440\u0438\u0431\u0440\u0435\u0436\u043d\u044b\u0445 \u0438 \u043a\u0430\u0431\u043e\u0442\u0430\u0436\u043d\u044b\u0445 \u043f\u0435\u0440\u0435\u0432\u043e\u0437\u043e\u043a.\u000a\u000d\u000a\u041e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0438\u0435 \u043e \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u044f\u0445 \u0441\u0434\u0435\u043b\u0430\u043d\u043e \u000d\u000a\u0432\u00a0\u0445\u043e\u0434\u0435 \u043c\u0435\u0440\u043e\u043f\u0440\u0438\u044f\u0442\u0438\u044f India Maritime Week. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u043f\u043e\u0434\u0447\u0435\u0440\u043a\u043d\u0443\u043b\u0430, \u0447\u0442\u043e \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u043e\u043d\u043d\u043e\u0435 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0431\u0443\u0434\u0435\u0442 \u000d\u000a\u0441\u043f\u043e\u0441\u043e\u0431\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044e \u0438\u043d\u0434\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u000d\u000a\u0438\u00a0\u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0435\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438.\u000d\u000a02 08","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438\u00a0\u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 31 \u043e\u043a\u0442\u044f\u0431\u0440\u044f \u2014 7 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0430\u000d\u000aAD Ports \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u0442 \u043f\u0435\u0440\u0432\u044b\u0435 \u0432 \u041e\u0410\u042d \u0447\u0430\u0441\u0442\u043d\u044b\u0435 \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b\u044b \u000d\u000a\u043f\u043e\u00a0\u043f\u0440\u0438\u0435\u043c\u0443 \u0433\u0430\u0437\u0430\u000d\u000a\u041f\u0440\u043e\u0435\u043a\u0442 \u043f\u0440\u0438\u0437\u0432\u0430\u043d \u0441\u0442\u0430\u0442\u044c \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u043c \u0445\u0430\u0431\u043e\u043c \u0434\u043b\u044f \u0438\u043c\u043f\u043e\u0440\u0442\u0430, \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u0438 \u043f\u0435\u0440\u0435\u0432\u0430\u043b\u043a\u0438 \u0433\u0430\u0437\u0430, \u0447\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442 \u0443\u0434\u043e\u0432\u043b\u0435\u0442\u0432\u043e\u0440\u0438\u0442\u044c \u000d\u000a\u0440\u0430\u0441\u0442\u0443\u0449\u0438\u0439 \u0441\u043f\u0440\u043e\u0441 \u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0430\u0437\u0438\u0430\u0442\u0441\u043a\u043e\u0433\u043e \u0440\u044b\u043d\u043a\u0430.\u000d\u000a\u042d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u0430\u044f \u0433\u0440\u0443\u043f\u043f\u0430 AD Ports \u0437\u0430\u043a\u043b\u044e\u0447\u0438\u043b\u0430 \u0441 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0435\u0439 \u000d\u000aNimex Terminals \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u043d\u0430 \u0441\u0443\u043c\u043c\u0443 $8,17 \u043c\u043b\u0440\u0434 \u000d\u000a\u043e\u00a0\u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0438 \u043f\u0435\u0440\u0432\u044b\u0445 \u0432 \u041e\u0410\u042d \u0447\u0430\u0441\u0442\u043d\u044b\u0445 \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b\u043e\u0432 \u043f\u043e \u043f\u0440\u0438\u0435\u043c\u0443 \u000d\u000a\u0438 \u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044e \u0441\u0436\u0438\u0436\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u0440\u0438\u0440\u043e\u0434\u043d\u043e\u0433\u043e \u0433\u0430\u0437\u0430 \u0438 \u0441\u0436\u0438\u0436\u0435\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u043d\u0435\u0444\u0442\u044f\u043d\u043e\u0433\u043e \u0433\u0430\u0437\u0430.\u000a\u000d\u000a\u0421\u043e\u0433\u043b\u0430\u0441\u043d\u043e AD Ports, \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u000d\u000a\u0437\u0430\u0439\u043c\u0435\u0442 \u043e\u043a\u043e\u043b\u043e \u043f\u044f\u0442\u0438 \u043b\u0435\u0442. \u041f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u0439 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441 \u000d\u000a\u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u044e\u000d\u000a\u043f\u043b\u043e\u0449\u0430\u0434\u044c\u044e 130 \u0442\u044b\u0441. \u043c2 \u0440\u0430\u0441\u043f\u043e\u043b\u043e\u0436\u0438\u0442\u0441\u044f \u0432 \u043f\u043e\u0440\u0442\u0443 \u0410\u0431\u0443-\u0414\u0430\u0431\u0438 \u000d\u000a\u043d\u0430\u00a0\u0431\u0435\u0440\u0435\u0433\u0443 \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430.\u000a\u000d\u000a\u041f\u043e \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u043c \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u0430, AD Ports \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u0443\u0435\u0442 \u2028\u000d\u000a\u0434\u043e $354,22 \u043c\u043b\u043d \u0432 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b. Nimex \u0432\u043b\u043e\u0436\u0438\u0442 \u000d\u000a\u0434\u043e $708,45 \u043c\u043b\u043d \u0432 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0440\u0435\u0437\u0435\u0440\u0432\u0443\u0430\u0440\u043e\u0432 \u0434\u043b\u044f \u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u000d\u000a\u0441\u0436\u0438\u0436\u0435\u043d\u043d\u043e\u0433\u043e \u0433\u0430\u0437\u0430 \u0438 \u0441\u043e\u043f\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0445 \u043e\u0431\u044a\u0435\u043a\u0442\u043e\u0432.\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430\u000d\u000a\u041d\u0430\u0441\u043b\u0435\u0434\u043d\u044b\u0439 \u043f\u0440\u0438\u043d\u0446 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u043f\u043e\u0441\u0435\u0442\u0438\u0442 \u000d\u000a\u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d 18 \u043d\u043e\u044f\u0431\u0440\u044f\u000d\u000a\u0412\u0438\u0437\u0438\u0442 \u0441\u043e\u0441\u0442\u043e\u0438\u0442\u0441\u044f \u043d\u0430 \u0444\u043e\u043d\u0435 \u0443\u0441\u0438\u043b\u0438\u0439 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438 \u043f\u043e \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u044e \u00ab\u0410\u0432\u0440\u0430\u0430\u043c\u043e\u0432\u044b\u0445 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0439\u00bb, \u000d\u000a\u0432\u00a0\u0440\u0430\u043c\u043a\u0430\u0445 \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0440\u044f\u0434 \u0430\u0440\u0430\u0431\u0441\u043a\u0438\u0445 \u0441\u0442\u0440\u0430\u043d \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0438 \u0434\u0438\u043f\u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f \u0441 \u0418\u0437\u0440\u0430\u0438\u043b\u0435\u043c.\u000d\u000a\u041d\u0430\u0441\u043b\u0435\u0434\u043d\u044b\u0439 \u043f\u0440\u0438\u043d\u0446 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u041c\u0443\u0445\u0430\u043c\u043c\u0435\u0434 \u0431\u0435\u043d \u000d\u000a\u0421\u0430\u043b\u043c\u0430\u043d \u0410\u043b\u044c \u0421\u0430\u0443\u0434 \u0441\u043e\u0432\u0435\u0440\u0448\u0438\u0442 18 \u043d\u043e\u044f\u0431\u0440\u044f \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0432\u0438\u0437\u0438\u0442 \u000d\u000a\u0432 \u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d, \u0433\u0434\u0435 \u0432\u0441\u0442\u0440\u0435\u0442\u0438\u0442\u0441\u044f \u0441 \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u043e\u043c \u0421\u0428\u0410 \u000d\u000a\u0414\u043e\u043d\u0430\u043b\u044c\u0434\u043e\u043c \u0422\u0440\u0430\u043c\u043f\u043e\u043c. \u041e\u0431 \u044d\u0442\u043e\u043c \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c \u000d\u000a\u0411\u0435\u043b\u043e\u0433\u043e \u0434\u043e\u043c\u0430.\u000a\u000d\u000a\u041e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0442\u0435\u043c\u043e\u0439 \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u043e\u0432 \u0441\u0442\u0430\u043d\u0435\u0442 \u043f\u0440\u0438\u0441\u043e\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0435 \u000d\u000a\u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430 \u043a \u00ab\u0410\u0432\u0440\u0430\u0430\u043c\u043e\u0432\u044b\u043c \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f\u043c\u00bb, \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430\u043c\u0438 \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u041e\u0410\u042d, \u0411\u0430\u0445\u0440\u0435\u0439\u043d \u0438 \u041c\u0430\u0440\u043e\u043a\u043a\u043e. \u0421\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f \u000d\u000a\u043e \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0439 \u0441 \u0418\u0437\u0440\u0430\u0438\u043b\u0435\u043c \u0431\u044b\u043b\u0438 \u0437\u0430\u043a\u043b\u044e\u0447\u0435\u043d\u044b \u000d\u000a\u043f\u0440\u0438 \u043f\u043e\u0441\u0440\u0435\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u0435 \u0421\u0428\u0410 \u0432\u043e \u0432\u0440\u0435\u043c\u044f \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u0441\u0440\u043e\u043a\u0430 \u000d\u000a\u0422\u0440\u0430\u043c\u043f\u0430.\u000a\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u0432\u043e\u0437\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043e\u0442 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u000d\u000a\u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0439 \u0441 \u0418\u0437\u0440\u0430\u0438\u043b\u0435\u043c, \u043d\u0430\u0441\u0442\u0430\u0438\u0432\u0430\u044f \u043d\u0430 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u000d\u000a\u043f\u0440\u0438\u0437\u043d\u0430\u0442\u044c \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u044c \u043f\u0430\u043b\u0435\u0441\u0442\u0438\u043d\u0441\u043a\u043e\u0433\u043e \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0430. \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u000d\u000a\u0412\u00a0\u043d\u0435\u0434\u0430\u0432\u043d\u0435\u043c \u0438\u043d\u0442\u0435\u0440\u0432\u044c\u044e \u0442\u0435\u043b\u0435\u043a\u0430\u043d\u0430\u043b\u0443 CBS \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 \u0421\u0428\u0410 \u000d\u000a\u0432\u044b\u0440\u0430\u0437\u0438\u043b \u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u044c, \u0447\u0442\u043e \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u00ab\u0432 \u0438\u0442\u043e\u0433\u0435 \u000d\u000a\u043f\u0440\u0438\u0441\u043e\u0435\u0434\u0438\u043d\u0438\u0442\u0441\u044f\u00bb \u043a \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f\u043c.\u000a\u000d\u000a\u041f\u043e \u0434\u0430\u043d\u043d\u044b\u043c Financial Times, \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0442\u0430\u043a\u0436\u0435 \u043c\u043e\u0433\u0443\u0442 \u043e\u0431\u0441\u0443\u0434\u0438\u0442\u044c \u000d\u000a\u043f\u0440\u043e\u0435\u043a\u0442 \u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0435\u0433\u043e \u043e\u0431\u043e\u0440\u043e\u043d\u043d\u043e\u0433\u043e \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f. \u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u0434\u043e\u0431\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043e\u0442 \u0421\u0428\u0410 \u0444\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0439 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u043a \u0441\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u043c \u000d\u000a\u0432\u0438\u0434\u0430\u043c \u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u0438\u044f \u0432 \u043e\u0431\u043c\u0435\u043d \u043d\u0430 \u043f\u0440\u0438\u0437\u043d\u0430\u043d\u0438\u0435 \u0438\u0437\u0440\u0430\u0438\u043b\u044c\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0430.\u000a\u000d\u000a\u0420\u0430\u043d\u0435\u0435 \u0421\u0428\u0410 \u0438 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u0437\u0430\u043a\u043b\u044e\u0447\u0438\u043b\u0438 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u000d\u000a\u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0435 \u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u0438\u044f \u043d\u0430 \u0441\u0443\u043c\u043c\u0443 $142 \u043c\u043b\u0440\u0434. \u000d\u000a\u0414\u043e\u0433\u043e\u0432\u043e\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0431\u044b\u043b\u0430 \u0434\u043e\u0441\u0442\u0438\u0433\u043d\u0443\u0442\u0430 \u0432\u043e \u0432\u0440\u0435\u043c\u044f \u0432\u0438\u0437\u0438\u0442\u0430 \u000d\u000a\u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u0432 \u042d\u0440-\u0420\u0438\u044f\u0434 \u0432 \u043c\u0430\u0435 \u044d\u0442\u043e\u0433\u043e \u0433\u043e\u0434\u0430.\u000d\u000a03 08","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438\u00a0\u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 31 \u043e\u043a\u0442\u044f\u0431\u0440\u044f \u2014 7 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u0438\u044f\u000d\u000a\u0421\u0428\u0410 \u043c\u043e\u0433\u0443\u0442 \u043e\u0434\u043e\u0431\u0440\u0438\u0442\u044c \u043f\u0440\u043e\u0434\u0430\u0436\u0443 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u000d\u000a\u0438\u0441\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u0435\u0439 F-35\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f, \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044c \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0445 \u0432\u0438\u0434\u043e\u0432 \u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u0438\u044f, \u0431\u043e\u043b\u044c\u0448\u0435 10 \u043b\u0435\u0442 \u043f\u044b\u0442\u0430\u0435\u0442\u0441\u044f \u000d\u000a\u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0441\u0442\u0438 F-35 \u0434\u043b\u044f \u043c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0430\u0446\u0438\u0438 \u0432\u043e\u0437\u0434\u0443\u0448\u043d\u044b\u0445 \u0441\u0438\u043b. \u0412 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0435 \u044d\u0442\u043e\u0439 \u0441\u0434\u0435\u043b\u043a\u0438 \u0418\u0437\u0440\u0430\u0438\u043b\u044c \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u0442\u0435\u0440\u044f\u0442\u044c \u043c\u043e\u043d\u043e\u043f\u043e\u043b\u0438\u044e \u000d\u000a\u043d\u0430 \u044d\u043a\u0441\u043f\u043b\u0443\u0430\u0442\u0430\u0446\u0438\u044e F-35 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435.\u000d\u000a\u0410\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0430\u044f \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u0440\u0430\u0441\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442 \u0437\u0430\u043f\u0440\u043e\u0441 \u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u043d\u0430 \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0435\u043d\u0438\u0435 48 \u0438\u0441\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u0435\u0439 \u000d\u000a\u043f\u044f\u0442\u043e\u0433\u043e \u043f\u043e\u043a\u043e\u043b\u0435\u043d\u0438\u044f F-35. \u041e\u0431\u043e\u0440\u043e\u043d\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u000d\u000a\u0437\u0430\u043a\u043b\u044e\u0447\u0435\u043d \u0432\u043e \u0432\u0440\u0435\u043c\u044f \u0432\u0438\u0437\u0438\u0442\u0430 \u0441\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0433\u043e \u043d\u0430\u0441\u043b\u0435\u0434\u043d\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u0438\u043d\u0446\u0430 \u041c\u0443\u0445\u0430\u043c\u043c\u0435\u0434\u0430 \u0431\u0435\u043d \u0421\u0430\u043b\u043c\u0430\u043d\u0430 \u0432 \u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d, \u000d\u000aReuters \u0441\u043e \u0441\u0441\u044b\u043b\u043a\u043e\u0439 \u043d\u0430 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438 \u0432 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u043c \u000d\u000a\u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0435.\u000a\u000d\u000a\u0421\u0435\u0439\u0447\u0430\u0441 \u0418\u0437\u0440\u0430\u0438\u043b\u044c \u2014 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f \u0431\u043b\u0438\u0436\u043d\u0435\u0432\u043e\u0441\u0442\u043e\u0447\u043d\u0430\u044f \u000d\u000a\u0441\u0442\u0440\u0430\u043d\u0430, \u044d\u043a\u0441\u043f\u043b\u0443\u0430\u0442\u0438\u0440\u0443\u044e\u0449\u0430\u044f \u0438\u0441\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u0438 F-35. \u041f\u0440\u043e\u0434\u0430\u0436\u0430 \u044d\u0442\u0438\u0445 \u000d\u000a\u0441\u0430\u043c\u043e\u043b\u0435\u0442\u043e\u0432 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u0431\u0443\u0434\u0435\u0442 \u043e\u0437\u043d\u0430\u0447\u0430\u0442\u044c \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u043e\u000d\u000a\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0441\u0434\u0432\u0438\u0433 \u0432 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0435 \u000d\u000a\u043f\u043e\u00a0\u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044e \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u0432\u043e\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u0440\u0435\u0432\u043e\u0441\u0445\u043e\u0434\u0441\u0442\u0432\u0430 \u000d\u000a\u0418\u0437\u0440\u0430\u0438\u043b\u044f \u0432 \u0431\u043e\u0435\u0432\u043e\u0439 \u0430\u0432\u0438\u0430\u0446\u0438\u0438 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435.\u000a\u000d\u000a\u041f\u043e\u043a\u0430 \u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d \u043d\u0435 \u043f\u0440\u0438\u043d\u044f\u043b \u043e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u2014 \u000d\u000a\u0434\u043b\u044f \u043d\u0435\u0433\u043e \u043f\u043e\u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f \u043e\u0434\u043e\u0431\u0440\u0435\u043d\u0438\u0435 \u0422\u0440\u0430\u043c\u043f\u0430, \u0435\u0433\u043e \u000d\u000a\u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438 \u0438 \u041a\u043e\u043d\u0433\u0440\u0435\u0441\u0441\u0430. \u041f\u043e\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0434\u0435\u043f\u0430\u0440\u0442\u0430\u043c\u0435\u043d\u0442 \u000d\u000a\u041f\u0435\u043d\u0442\u0430\u0433\u043e\u043d\u0430 \u0440\u0430\u0431\u043e\u0442\u0430\u043b \u043d\u0430\u0434 \u044d\u0442\u0438\u043c \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u043e\u043c \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u000d\u000a\u043c\u0435\u0441\u044f\u0446\u0435\u0432, \u043f\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043c \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u043f\u043e\u043f\u0430\u043b \u043d\u0430 \u0440\u0430\u0441\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u0438\u0435 \u000d\u000a\u043a\u00a0\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0443 \u0432\u043e\u0439\u043d\u044b \u041f\u0438\u0442\u0443 \u0425\u0435\u0433\u0441\u0435\u0442\u0443.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0422\u0443\u0440\u0446\u0438\u044f \u0441\u043e\u0437\u0434\u0430\u0441\u0442 \u043f\u0440\u043e\u043c\u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441 \u043f\u043e \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0435 \u000d\u000a\u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432\u000d\u000a\u0420\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0430 \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u0430 \u0441\u0442\u0430\u0442\u044c \u043e\u0434\u043d\u0438\u043c \u0438\u0437 \u0432\u0435\u0434\u0443\u0449\u0438\u0445 \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a\u043e\u0432 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432. \u0417\u0430 \u0441\u0447\u0435\u0442 \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u0432 \u0438\u0445 \u0434\u043e\u0431\u044b\u0447\u0443 \u0438 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0443 \u0441\u0442\u0440\u0430\u043d\u0430 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442 \u0443\u043a\u0440\u0435\u043f\u0438\u0442\u044c \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u0435 \u043f\u043e\u0437\u0438\u0446\u0438\u0438.\u00a0\u000d\u000a\u0422\u0443\u0440\u0446\u0438\u044f \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0432 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u043c \u0433\u043e\u0434\u0443 \u043f\u0440\u0438\u0441\u0442\u0443\u043f\u0438\u0442\u044c \u000d\u000a\u043a\u00a0\u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0443 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u000d\u000a\u043f\u043e\u00a0\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0435 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432. \u0417\u0430\u043f\u0443\u0441\u043a \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043e\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044f \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 \u0434\u0432\u0443\u0445 \u043b\u0435\u0442, \u000d\u000a\u043c\u0438\u043d\u0438\u0441\u0442\u0440 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438 \u0438 \u043f\u0440\u0438\u0440\u043e\u0434\u043d\u044b\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u0441\u0442\u0440\u0430\u043d\u044b \u000d\u000a\u0410\u043b\u043f\u0430\u0440\u0441\u043b\u0430\u043d \u0411\u0430\u0439\u0440\u0430\u043a\u0442\u0430\u0440.\u000a\u000d\u000a\u0412 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u0435 \u0432\u0440\u0435\u043c\u044f \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442\u0441\u044f \u0440\u0430\u0431\u043e\u0442\u0430 \u043f\u0438\u043b\u043e\u0442\u043d\u043e\u0433\u043e \u000d\u000a\u0437\u0430\u0432\u043e\u0434\u0430, \u0441\u043e\u0437\u0434\u0430\u043d\u043d\u043e\u0433\u043e \u0432 2020 \u0433\u043e\u0434\u0443 \u0432 \u0440\u0430\u0439\u043e\u043d\u0435 \u0411\u0435\u0439\u043b\u044b\u043a\u043e\u0432\u0430 \u000d\u000a\u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u042d\u0441\u043a\u0438\u0448\u0435\u0445\u0438\u0440. \u041f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435 \u0431\u044b\u043b\u043e \u0432\u0432\u0435\u0434\u0435\u043d\u043e \u000d\u000a\u0432\u00a0\u044d\u043a\u0441\u043f\u043b\u0443\u0430\u0442\u0430\u0446\u0438\u044e \u0432 2023 \u0433\u043e\u0434\u0443 \u0438 \u0442\u0435\u043f\u0435\u0440\u044c \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0438\u0442 \u000d\u000a\u043a\u00a0\u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u043c\u0443 \u044d\u0442\u0430\u043f\u0443 \u2014 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u044e \u0434\u043e \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0430.\u000a\u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b\u000d\u000a\u0411\u0430\u0439\u0440\u0430\u043a\u0442\u0430\u0440 \u043e\u0442\u043c\u0435\u0442\u0438\u043b, \u0447\u0442\u043e \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0430 \u000d\u000a\u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u0442\u0430\u043a\u0436\u0435 \u0432\u0435\u0434\u0435\u0442\u0441\u044f \u0432 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f\u0445 \u000d\u000a\u0418\u0441\u043f\u0430\u0440\u0442\u0430, \u041c\u0430\u043b\u0430\u0442\u044c\u044f \u0438 \u0421\u0438\u0432\u0430\u0441. \u0412 \u043c\u0430\u0435 \u043c\u0438\u043d\u0438\u0441\u0442\u0440 \u043d\u0430\u0437\u0432\u0430\u043b \u000d\u000a\u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0439 \u0441\u0435\u043a\u0442\u043e\u0440 \u043e\u0434\u043d\u0438\u043c \u0438\u0437 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0445 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0439 \u000d\u000a\u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0435\u043d\u0438\u044f \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u000d\u000a\u0438\u00a0\u0438\u043d\u0434\u0443\u0441\u0442\u0440\u0438\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0422\u0443\u0440\u0446\u0438\u0438.\u000d\u000a04 08","\u041a\u0438\u0442\u0430\u0439 31 \u043e\u043a\u0442\u044f\u0431\u0440\u044f \u2014 7 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u041f\u0440\u043e\u0442\u0435\u0441\u0442\u044b \u0432 \u0422\u0430\u043d\u0437\u0430\u043d\u0438\u0438 \u0432\u044b\u0437\u0432\u0430\u043b\u0438 \u043f\u0435\u0440\u0435\u0431\u043e\u0438 \u0432 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0430\u0445 \u000d\u000a\u043c\u0435\u0434\u0438 \u0432 \u041a\u0438\u0442\u0430\u0439\u000d\u000a\u0414\u0430\u0440-\u044d\u0441-\u0421\u0430\u043b\u0430\u043c \u2014 \u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0439 \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0443\u0437\u0435\u043b \u0434\u043b\u044f \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u043a\u0438 \u043c\u0435\u0434\u0438 \u0438 \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430 \u0438\u0437 \u041a\u043e\u043d\u0433\u043e \u0438 \u0417\u0430\u043c\u0431\u0438\u0438. \u0427\u0435\u0440\u0435\u0437 \u000d\u000a\u043d\u0435\u0433\u043e \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442 \u043e\u043a\u043e\u043b\u043e 70% \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u0430\u0444\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u043c\u0435\u0434\u0438 \u0432 \u041a\u041d\u0420.\u00a0\u000d\u000a\u041f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u043c\u0435\u0434\u0438 \u0438\u0437 \u0410\u0444\u0440\u0438\u043a\u0438 \u0432 \u041a\u0438\u0442\u0430\u0439 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u044b \u0438\u0437-\u0437\u0430 \u000d\u000a\u043f\u0440\u043e\u0442\u0435\u0441\u0442\u043e\u0432 \u0432 \u0422\u0430\u043d\u0437\u0430\u043d\u0438\u0438, \u0432\u044b\u0437\u0432\u0430\u0432\u0448\u0438\u0445 \u0441\u0431\u043e\u0438 \u0432 \u0440\u0430\u0431\u043e\u0442\u0435 \u043f\u043e\u0440\u0442\u0430 \u000d\u000a\u0414\u0430\u0440-\u044d\u0441-\u0421\u0430\u043b\u0430\u043c. \u0422\u0440\u0435\u0439\u0434\u0435\u0440\u044b \u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u043c\u0435\u0442\u0430\u043b\u043b\u0430 \u000d\u000a\u0432\u044b\u043d\u0443\u0436\u0434\u0435\u043d\u044b \u0438\u0441\u043a\u0430\u0442\u044c \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0435 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u044b, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u000d\u000a\u044e\u0436\u043d\u043e\u0430\u0444\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0439 \u043f\u043e\u0440\u0442 \u0414\u0443\u0440\u0431\u0430\u043d, Bloomberg.\u000a\u000d\u000a\u0421\u0435\u0439\u0447\u0430\u0441 \u043f\u043e\u0440\u0442 \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b \u0440\u0430\u0431\u043e\u0442\u0443 \u2014 \u043e\u0442\u0433\u0440\u0443\u0437\u043a\u0438 \u043d\u0435 \u0432\u0435\u0434\u0443\u0442\u0441\u044f, \u000d\u000a\u0434\u043e\u0441\u0442\u0443\u043f \u043a \u0441\u043a\u043b\u0430\u0434\u0430\u043c \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u043f\u0435\u0440\u0435\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0442 \u000d\u000a\u0433\u0440\u0443\u0437\u044b \u0432 \u0434\u0440\u0443\u0433\u0438\u0435 \u0430\u0444\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0435 \u043f\u043e\u0440\u0442\u044b \u2014 \u0414\u0443\u0440\u0431\u0430\u043d (\u042e\u0410\u0420), \u000d\u000a\u0423\u043e\u043b\u0444\u0438\u0448-\u0411\u0435\u0439 (\u041d\u0430\u043c\u0438\u0431\u0438\u044f) \u0438 \u0411\u0435\u0439\u0440\u0430 (\u041c\u043e\u0437\u0430\u043c\u0431\u0438\u043a).\u000d\u000a\u043f\u0435\u0440\u0435\u0434\u0430\u0435\u0442\u000d\u000a\u041f\u0440\u043e\u0442\u0435\u0441\u0442\u044b \u0432\u0441\u043f\u044b\u0445\u043d\u0443\u043b\u0438 \u043f\u043e\u0441\u043b\u0435 \u0432\u0441\u0435\u043e\u0431\u0449\u0438\u0445 \u0432\u044b\u0431\u043e\u0440\u043e\u0432 \u2028\u000d\u000a29 \u043e\u043a\u0442\u044f\u0431\u0440\u044f \u0438 \u043f\u0435\u0440\u0435\u0440\u043e\u0441\u043b\u0438 \u0432 \u0431\u0435\u0441\u043f\u043e\u0440\u044f\u0434\u043a\u0438: \u043f\u0440\u043e\u0442\u0435\u0441\u0442\u0443\u044e\u0449\u0438\u0435 \u000d\u000a\u0430\u0442\u0430\u043a\u043e\u0432\u0430\u043b\u0438 \u043f\u043e\u043b\u0438\u0446\u0438\u044e, \u043f\u043e\u0434\u0436\u0438\u0433\u0430\u043b\u0438 \u0430\u0432\u0442\u043e\u043c\u043e\u0431\u0438\u043b\u0438 \u0438 \u0437\u0430\u043f\u0440\u0430\u0432\u043a\u0438. \u000d\u000a\u041f\u043e\u0432\u043e\u0434\u043e\u043c \u0441\u0442\u0430\u043b\u043e \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u0438\u0437 \u043f\u0440\u0435\u0434\u0432\u044b\u0431\u043e\u0440\u043d\u043e\u0439 \u0433\u043e\u043d\u043a\u0438 \u0434\u0432\u0443\u0445 \u000d\u000a\u0433\u043b\u0430\u0432\u043d\u044b\u0445 \u0441\u043e\u043f\u0435\u0440\u043d\u0438\u043a\u043e\u0432 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0433\u043e \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430. \u000d\u000a\u041f\u0440\u0430\u0432\u043e\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043e\u0440\u0433\u0430\u043d\u044b \u043f\u0440\u0438\u043c\u0435\u043d\u0438\u043b\u0438 \u0441\u043b\u0435\u0437\u043e\u0442\u043e\u0447\u0438\u0432\u044b\u0439 \u000d\u000a\u0433\u0430\u0437 \u0438 \u0431\u043e\u0435\u0432\u044b\u0435 \u043f\u0430\u0442\u0440\u043e\u043d\u044b.\u000d\u000a05 08","\u041a\u0438\u0442\u0430\u0439 31 \u043e\u043a\u0442\u044f\u0431\u0440\u044f \u2014 7 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438\u000d\u000aCMOC \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u0443\u0435\u0442 $1,08 \u043c\u043b\u0440\u0434 \u0432 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u2028\u000d\u000a\u043c\u0435\u0434\u043d\u043e-\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u043e\u0432\u043e\u0433\u043e \u0440\u0443\u0434\u043d\u0438\u043a\u0430 \u0432 \u0414\u0420\u041a\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0432 \u043c\u0438\u0440\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430 China Molybdenum (CMOC Group) \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u2028\u000d\u000a$1,08 \u043c\u043b\u0440\u0434 \u0432 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044e \u0432\u0442\u043e\u0440\u043e\u0439 \u043e\u0447\u0435\u0440\u0435\u0434\u0438 \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u043f\u043e \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044e \u043c\u0435\u0434\u043d\u043e-\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u043e\u0432\u043e\u0433\u043e \u0440\u0443\u0434\u043d\u0438\u043a\u0430 \u0432 \u041a\u043e\u043d\u0433\u043e.\u000d\u000a\u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442\u000d\u000a\u0420\u0430\u0431\u043e\u0442\u044b \u043d\u0430\u0434 \u0432\u0442\u043e\u0440\u043e\u0439 \u043e\u0447\u0435\u0440\u0435\u0434\u044c\u044e \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u000d\u000a\u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044c \u0432 2027 \u0433\u043e\u0434\u0443. \u041e\u043a\u043e\u043b\u043e $859 \u043c\u043b\u043d \u0431\u0443\u0434\u0443\u0442 \u000d\u000a\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u044b \u043d\u0430 \u0438\u043d\u0436\u0435\u043d\u0435\u0440\u0438\u044e, \u0430 $109 \u043c\u043b\u043d \u2014 \u000d\u000a\u043d\u0430\u00a0\u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0440\u0430\u0441\u0445\u043e\u0434\u044b. \u0415\u0449\u0435 $116 \u043c\u043b\u043d \u0437\u0430\u043b\u043e\u0436\u0435\u043d\u044b \u000d\u000a\u0432\u00a0\u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435 \u0440\u0435\u0437\u0435\u0440\u0432\u0430 \u043d\u0430 \u043f\u0440\u043e\u0447\u0438\u0435 \u0438\u0437\u0434\u0435\u0440\u0436\u043a\u0438.\u000a\u000d\u000a\u0412\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u0432 \u044d\u043a\u0441\u043f\u043b\u0443\u0430\u0442\u0430\u0446\u0438\u044e \u0432\u0442\u043e\u0440\u043e\u0439 \u043e\u0447\u0435\u0440\u0435\u0434\u0438 \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442 \u000d\u000a\u043d\u0430\u0440\u0430\u0441\u0442\u0438\u0442\u044c \u043e\u0431\u044a\u0435\u043c\u044b \u0434\u043e\u0431\u044b\u0447\u0438 \u0438 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u0440\u0443\u0434\u044b \u2028\u000d\u000a\u043d\u0430 7,26 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434, \u0430 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043c\u0435\u0434\u0438 \u2014 \u2028\u000d\u000a\u043d\u0430 100 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d.\u000a\u000d\u000a\u041e\u043f\u0435\u0440\u0430\u0442\u043e\u0440 \u0440\u0443\u0434\u043d\u0438\u043a\u0430 \u0432\u043b\u0430\u0434\u0435\u0435\u0442 71,25% \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u0438 \u0432\u044b\u0432\u0435\u043b \u000d\u000a\u043f\u0435\u0440\u0432\u0443\u044e \u043e\u0447\u0435\u0440\u0435\u0434\u044c \u043d\u0430 \u043f\u043e\u043b\u043d\u0443\u044e \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u0432 2023 \u0433\u043e\u0434\u0443. \u000d\u000a\u0421\u0435\u0439\u0447\u0430\u0441 \u043d\u0430 \u041a\u0438\u0441\u0430\u043d\u0444\u0443 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0441\u044f 150 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u000d\u000a\u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0442\u0430 \u043c\u0435\u0434\u0438 \u0438 \u043e\u043a\u043e\u043b\u043e 50 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430 \u0432 \u0433\u043e\u0434.\u000a\u000d\u000aCMOC Group \u0441\u043c\u0435\u0441\u0442\u0438\u043b\u0430 \u0448\u0432\u0435\u0439\u0446\u0430\u0440\u0441\u043a\u0443\u044e Glencore \u0441 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u000d\u000a\u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u043b\u0438\u0434\u0435\u0440\u0430 \u043f\u043e \u0434\u043e\u0431\u044b\u0447\u0435 \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430 \u0432 2023 \u0433\u043e\u0434\u0443. \u000d\u000a\u041f\u043e\u00a0\u0438\u0442\u043e\u0433\u0430\u043c 2024 \u0433\u043e\u0434\u0430 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043d\u0430\u0440\u0430\u0441\u0442\u0438\u043b\u0430 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043c\u0435\u0434\u0438 \u043d\u0430 55%, \u0434\u043e 650,2 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d. \u0420\u043e\u0441\u0442 \u0431\u044b\u043b \u000d\u000a\u0434\u043e\u0441\u0442\u0438\u0433\u043d\u0443\u0442 \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u044f \u0434\u0432\u0443\u043c \u0440\u0443\u0434\u043d\u0438\u043a\u0430\u043c \u0432 \u0414\u0420\u041a: \u2028\u000d\u000a\u0422\u0435\u043d\u043a\u0435-\u0424\u0443\u043d\u0433\u0443\u0440\u0443\u043c\u0435 \u0438 \u041a\u0438\u0441\u0430\u043d\u0444\u0443.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b \u043d\u0430\u043b\u043e\u0433\u043e\u0432\u044b\u0435 \u043b\u044c\u0433\u043e\u0442\u044b \u2028\u000d\u000a\u043d\u0430 \u043f\u0435\u0440\u0435\u043f\u0440\u043e\u0434\u0430\u0436\u0443 \u0437\u043e\u043b\u043e\u0442\u0430\u00a0\u000d\u000a\u041c\u0438\u043d\u0444\u0438\u043d \u041a\u041d\u0420 \u0441 1 \u043d\u043e\u044f\u0431\u0440\u044f \u043d\u0430\u043b\u043e\u0433\u043e\u0432\u044b\u0435 \u043b\u044c\u0433\u043e\u0442\u044b \u043d\u0430 \u0441\u0434\u0435\u043b\u043a\u0438 \u0441 \u0437\u043e\u043b\u043e\u0442\u043e\u043c. \u041e\u043d\u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u043b\u0438 20 \u043b\u0435\u0442.\u00a0 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b\u000d\u000a\u0420\u0430\u043d\u0435\u0435 \u0440\u0438\u0442\u0435\u0439\u043b\u0435\u0440\u044b \u043c\u043e\u0433\u043b\u0438 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0442\u044c \u043d\u0430 \u043f\u043e\u043b\u043d\u0443\u044e \u000d\u000a\u043a\u043e\u043c\u043f\u0435\u043d\u0441\u0430\u0446\u0438\u044e \u041d\u0414\u0421 \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u043e\u0439 13% \u043f\u0440\u0438 \u043f\u0435\u0440\u0435\u043f\u0440\u043e\u0434\u0430\u0436\u0435 \u000d\u000a\u0437\u043e\u043b\u043e\u0442\u0430, \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0435\u043d\u043d\u043e\u0433\u043e \u043d\u0430 \u0428\u0430\u043d\u0445\u0430\u0439\u0441\u043a\u043e\u0439 \u0437\u043e\u043b\u043e\u0442\u043e\u0439 \u0431\u0438\u0440\u0436\u0435. \u000d\u000a\u0422\u0435\u043f\u0435\u0440\u044c \u0440\u0430\u0437\u043c\u0435\u0440 \u043a\u043e\u043c\u043f\u0435\u043d\u0441\u0430\u0446\u0438\u0438 \u0441\u043d\u0438\u0437\u0438\u043b\u0441\u044f \u0434\u043e 6%.\u000d\u000a\u041f\u0440\u0430\u0432\u0438\u043b\u043e \u0440\u0430\u0441\u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u0438\u043d\u0432\u0435\u0441\u0442\u043f\u0440\u043e\u0434\u0443\u043a\u0442\u044b \u0438\u0437 \u0437\u043e\u043b\u043e\u0442\u0430, \u000d\u000a\u0432 \u0442\u043e\u043c \u0447\u0438\u0441\u043b\u0435 \u0441\u043b\u0438\u0442\u043a\u0438 \u0438 \u043c\u043e\u043d\u0435\u0442\u044b, \u0430 \u0442\u0430\u043a\u0436\u0435 \u043d\u0430 \u044e\u0432\u0435\u043b\u0438\u0440\u043d\u044b\u0435 \u000d\u000a\u0438\u0437\u0434\u0435\u043b\u0438\u044f \u0438 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u0435 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u044b.\u000d\u000a06 08","\u041a\u0438\u0442\u0430\u0439 31 \u043e\u043a\u0442\u044f\u0431\u0440\u044f \u2014 7 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438\u000d\u000aChinalco \u0441\u043e\u0437\u0434\u0430\u0441\u0442 \u0421\u041f \u043f\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u000d\u000a\u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432\u000d\u000a\u041e\u0434\u0438\u043d \u0438\u0437 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0432 \u043c\u0438\u0440\u0435, Aluminum Corporation of China (Chinalco), \u000d\u000a\u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e\u0435 \u0441 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u043c\u0438 \u043f\u0430\u0440\u0442\u043d\u0435\u0440\u0430\u043c\u0438 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435 \u043f\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432.\u000d\u000a\u0441\u043e\u0437\u0434\u0430\u0435\u0442\u000d\u000a\u0414\u043e\u043b\u044f Chinalco \u0432 \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u0435 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u0442 25%, \u0430 \u0434\u0432\u0435 \u0435\u0435 \u000d\u000a\u0434\u043e\u0447\u0435\u0440\u043d\u0438\u0435 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u2014 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u0433\u043b\u0438\u043d\u043e\u0437\u0435\u043c\u0430 \u000d\u000a\u0438\u00a0\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f Chalco, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u043e\u043d\u043d\u0430\u044f Chinalco \u000d\u000aCapital Holdings \u2014 \u0431\u0443\u0434\u0443\u0442 \u0432\u043b\u0430\u0434\u0435\u0442\u044c 20% \u0438 15%.\u000a\u000d\u000a\u041a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e, \u0432 \u0421\u041f \u0432\u043e\u0439\u0434\u0443\u0442 Yunnan Chihong Zinc \u000d\u000aand\u00a0Germanium (20%) \u0438 Yunnan Copper (20%). \u0423\u0441\u0442\u0430\u0432\u043d\u043e\u0439 \u000d\u000a\u043a\u0430\u043f\u0438\u0442\u0430\u043b \u043d\u043e\u0432\u043e\u0433\u043e \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u0442 \u043e\u043a\u043e\u043b\u043e $211 \u043c\u043b\u043d.\u000d\u000aChalco \u043f\u0435\u0440\u0435\u0434\u0430\u0441\u0442 \u0432 \u0441\u043e\u0441\u0442\u0430\u0432 \u0421\u041f \u0441\u0432\u043e\u0438 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u000d\u000a\u043f\u043e\u00a0\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u0433\u0430\u043b\u043b\u0438\u044f \u043d\u0430 \u0433\u043b\u0438\u043d\u043e\u0437\u0435\u043c\u043d\u044b\u0445 \u0437\u0430\u0432\u043e\u0434\u0430\u0445 \u0432 \u0433\u043e\u0440\u043e\u0434\u0435 \u000d\u000a\u0427\u0436\u044d\u043d\u0447\u0436\u043e\u0443 (\u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f \u0425\u044d\u043d\u0430\u043d\u044c). Yunnan Chihong Zinc \u000d\u000aand\u00a0Germanium \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u043b\u0430\u0441\u044c \u043f\u0435\u0440\u0435\u0434\u0430\u0442\u044c \u0432 \u043d\u043e\u0432\u043e\u0435 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0433\u0435\u0440\u043c\u0430\u043d\u0438\u044f Chihong Germanium.\u000a\u000d\u000a\u0421\u0442\u043e\u0440\u043e\u043d\u044b \u0434\u043e\u043b\u0436\u043d\u044b \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044c \u0441\u0432\u043e\u0438 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u000d\u000a\u043f\u043e\u00a0\u043f\u0435\u0440\u0435\u0434\u0430\u0447\u0435 \u0432 \u0441\u043e\u0441\u0442\u0430\u0432 \u0421\u041f \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0445 \u0441\u0440\u0435\u0434\u0441\u0442\u0432 \u0438 \u0430\u043a\u0442\u0438\u0432\u043e\u0432 \u000d\u000a\u043a\u00a0\u043a\u043e\u043d\u0446\u0443 \u0433\u043e\u0434\u0430.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f \u0443\u0436\u0435\u0441\u0442\u043e\u0447\u0438\u0442 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0437\u0430 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u044c\u044e \u000d\u000a\u0442\u0440\u0443\u0434\u0430 \u0432 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u043e\u0439 \u043e\u0442\u0440\u0430\u0441\u043b\u0438\u000d\u000a\u041f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0443\u0436\u0435\u0441\u0442\u043e\u0447\u0438\u0442 \u043d\u0430\u043a\u0430\u0437\u0430\u043d\u0438\u044f \u0434\u043b\u044f \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439 \u0437\u0430 \u043d\u0435\u0441\u043e\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u0435 \u043c\u0435\u0440 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0437\u0430 \u043e\u0442\u043a\u0430\u0437 \u043e\u0442 \u000d\u000a\u0443\u0441\u0442\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b\u0445 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0439.\u000d\u000a\u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u0442\u0440\u0443\u0434\u043e\u0432\u044b\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u000d\u000a \u0443\u0441\u0438\u043b\u0438\u0442\u044c \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0437\u0430 \u0441\u043e\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u0435\u043c \u043d\u043e\u0440\u043c \u000d\u000a\u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u043d\u0430 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0445 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f\u0445.\u000a\u000d\u000a\u0418\u043d\u0441\u043f\u0435\u043a\u0442\u043e\u0440 \u0432\u0435\u0434\u043e\u043c\u0441\u0442\u0432\u0430 \u0425\u044c\u044e\u0433\u043e \u041d\u0430\u0438\u043d\u0433\u043e\u043b\u0430\u043d \u0441\u043e\u043e\u0431\u0449\u0438\u043b, \u0447\u0442\u043e \u000d\u000a\u0441\u00a02019 \u043f\u043e 2025 \u0433\u043e\u0434 \u0432 \u043e\u0442\u0440\u0430\u0441\u043b\u0438 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e \u000d\u000a104\u00a0\u043d\u0435\u0441\u0447\u0430\u0441\u0442\u043d\u044b\u0445 \u0441\u043b\u0443\u0447\u0430\u044f, \u0432 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0435 \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u043f\u043e\u0433\u0438\u0431\u043b\u0438 \u000d\u000a107\u00a0\u0447\u0435\u043b\u043e\u0432\u0435\u043a \u0438 105 \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0438 \u0440\u0430\u043d\u0435\u043d\u0438\u044f. \u041e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u2028\u000d\u000a\u043f\u0440\u0438\u0447\u0438\u043d\u044b \u2014 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0435 \u0442\u0435\u0445\u043d\u0438\u043a\u0438 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u000d\u000a\u0438\u00a0\u0445\u0430\u043b\u0430\u0442\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u0438\u00a0\u044d\u043a\u0441\u043f\u043b\u0443\u0430\u0442\u0430\u0446\u0438\u0438 \u043e\u0431\u043e\u0440\u0443\u0434\u043e\u0432\u0430\u043d\u0438\u044f.\u000d\u000a\u043f\u043e\u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043b\u043e\u000d\u000a\u0412\u043b\u0430\u0441\u0442\u0438 \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u044b \u0432\u0432\u0435\u0441\u0442\u0438 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0435 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u000d\u000a\u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u044b (SOP), \u043f\u043e\u0432\u044b\u0441\u0438\u0442\u044c \u043a\u0432\u0430\u043b\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044e \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u043b\u0430 \u000d\u000a\u0438\u00a0\u043f\u0440\u043e\u0432\u043e\u0434\u0438\u0442\u044c \u0440\u0435\u0433\u0443\u043b\u044f\u0440\u043d\u044b\u0435 \u0438\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u0438. \u0422\u0430\u043a\u0436\u0435 \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u000d\u000a\u0441\u043e\u0437\u0434\u0430\u0442\u044c \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u043d\u0443\u044e \u0441\u0438\u0441\u0442\u0435\u043c\u0443 \u0434\u043b\u044f \u043f\u0440\u0438\u0435\u043c\u0430 \u0436\u0430\u043b\u043e\u0431 \u000d\u000a\u0438\u00a0\u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0439 \u043e \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u044f\u0445, \u0443\u0436\u0435\u0441\u0442\u043e\u0447\u0438\u0442\u044c \u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439 \u0438 \u043e\u0431\u043d\u043e\u0432\u0438\u0442\u044c \u0437\u0430\u043a\u043e\u043d \u043e \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u0442\u0440\u0443\u0434\u0430 \u000d\u000a1970\u00a0\u0433\u043e\u0434\u0430 \u0441 \u0443\u0447\u0435\u0442\u043e\u043c \u0441\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0445 \u0440\u0435\u0430\u043b\u0438\u0439.\u000a\u000d\u000a\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0437\u0430 \u0441\u043e\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u0435\u043c \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0439 \u0431\u0443\u0434\u0443\u0442 \u000d\u000a\u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043b\u044f\u0442\u044c \u0438 \u043f\u0440\u043e\u0444\u0441\u043e\u044e\u0437\u044b.\u000d\u000a07 08","\u041a\u0438\u0442\u0430\u0439 31 \u043e\u043a\u0442\u044f\u0431\u0440\u044f \u2014 7 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0442\u043e\u0440\u0433\u043e\u0432\u043b\u044f #\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u043e\u0442\u043b\u043e\u0436\u0438\u043b \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u000d\u000a\u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u043d\u0430 \u043e\u0434\u0438\u043d \u0433\u043e\u0434\u000d\u000a\u042d\u0442\u043e \u0441\u0442\u0430\u043b\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u043c \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u043e\u0432 \u043c\u0435\u0436\u0434\u0443 \u0421\u0438 \u0426\u0437\u0438\u043d\u044c\u043f\u0438\u043d\u043e\u043c \u0438 \u0414\u043e\u043d\u0430\u043b\u044c\u0434\u043e\u043c \u0422\u0440\u0430\u043c\u043f\u043e\u043c \u043d\u0430 \u043f\u043e\u043b\u044f\u0445 \u0441\u0430\u043c\u043c\u0438\u0442\u0430 \u2028\u000d\u000a\u0410\u0422\u042d\u0421 30 \u043e\u043a\u0442\u044f\u0431\u0440\u044f \u0432 \u042e\u0436\u043d\u043e\u0439 \u041a\u043e\u0440\u0435\u0435.\u000d\u000a\u041a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e, \u041a\u0438\u0442\u0430\u0439 \u0443\u0441\u0438\u043b\u0438\u0442\u044c \u0431\u043e\u0440\u044c\u0431\u0443 \u000d\u000a\u0441\u00a0\u043a\u043e\u043d\u0442\u0440\u0430\u0431\u0430\u043d\u0434\u043e\u0439 \u0444\u0435\u043d\u0442\u0430\u043d\u0438\u043b\u0430 \u0438 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u044c \u0437\u0430\u043a\u0443\u043f\u043a\u0438 \u000d\u000a\u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u0441\u0435\u043b\u044c\u0445\u043e\u0437\u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u2014 \u0434\u043e 12 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0441\u043e\u0435\u0432\u044b\u0445 \u000d\u000a\u0431\u043e\u0431\u043e\u0432 \u043a \u043a\u043e\u043d\u0446\u0443 \u0433\u043e\u0434\u0430 \u0438 \u043f\u043e 25 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0435\u0436\u0435\u0433\u043e\u0434\u043d\u043e \u000d\u000a\u0432\u00a0\u043f\u043e\u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0435 \u0442\u0440\u0438 \u0433\u043e\u0434\u0430. \u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d \u0441\u043d\u0438\u0437\u0438\u0442 \u043f\u043e\u0448\u043b\u0438\u043d\u044b \u000d\u000a\u043d\u0430\u00a0\u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 \u0442\u043e\u0432\u0430\u0440\u044b \u0441 57% \u0434\u043e 47%.\u000d\u000a\u0441\u043e\u0433\u043b\u0430\u0441\u0438\u043b\u0441\u044f \u0420\u0430\u043d\u0435\u0435, 9 \u043e\u043a\u0442\u044f\u0431\u0440\u044f, \u0432\u043b\u0430\u0441\u0442\u0438 \u041a\u041d\u0420 \u0443\u0436\u0435\u0441\u0442\u043e\u0447\u0438\u043b\u0438 \u0441\u0438\u0441\u0442\u0435\u043c\u0443 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f \u000d\u000a\u0438 \u043a\u0432\u043e\u0442 \u0434\u043b\u044f \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432, \u043e\u0431\u044f\u0437\u0430\u0432 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u043e\u0442\u0447\u0438\u0442\u044b\u0432\u0430\u0442\u044c\u0441\u044f \u043e\u0431 \u043e\u0431\u044a\u0435\u043c\u0430\u0445 \u0441\u044b\u0440\u044c\u044f, \u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u043d\u043d\u043e\u0439 \u000d\u000a\u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u0438 \u043a\u043e\u043d\u0435\u0447\u043d\u044b\u0445 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044f\u0445. \u041a \u043a\u043e\u043d\u0446\u0443 \u043c\u0435\u0441\u044f\u0446\u0430 \u000d\u000a\u043f\u043e\u0434\u00a0\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u043f\u043e\u0434\u043f\u0430\u043b\u0438 12 \u0438\u0437 17 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u0438 \u0441\u0432\u044f\u0437\u0430\u043d\u043d\u044b\u0445 \u0441 \u043d\u0438\u043c\u0438 \u0438\u0437\u0434\u0435\u043b\u0438\u0439, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u043c\u0430\u0433\u043d\u0438\u0442\u044b \u000d\u000a\u0438\u00a0\u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u044b \u0434\u043b\u044f \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u0438\u043a\u0438.\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000a\u0420\u0424 \u0438 \u041a\u0438\u0442\u0430\u0439 \u0443\u0433\u043b\u0443\u0431\u043b\u044f\u044e\u0442 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0432 \u043f\u0435\u0440\u0435\u0432\u043e\u0437\u043a\u0430\u0445 \u000d\u000a\u043f\u043e \u0421\u0435\u0432\u043c\u043e\u0440\u043f\u0443\u0442\u0438\u000d\u000a\u0420\u043e\u0441\u0441\u0438\u044f \u0438 \u041a\u0438\u0442\u0430\u0439 \u0431\u0443\u0434\u0443\u0442 \u0443\u0433\u043b\u0443\u0431\u043b\u044f\u0442\u044c \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0432 \u0410\u0440\u043a\u0442\u0438\u043a\u0435 \u0438 \u0440\u0430\u0441\u0448\u0438\u0440\u044f\u0442\u044c \u043f\u0435\u0440\u0435\u0432\u043e\u0437\u043a\u0438 \u043f\u043e \u0421\u0435\u0432\u0435\u0440\u043d\u043e\u043c\u0443 \u043c\u043e\u0440\u0441\u043a\u043e\u043c\u0443 \u043f\u0443\u0442\u0438, \u000d\u000a\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f \u0432 \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043d\u043d\u043e\u043c \u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0435\u043c \u043a\u043e\u043c\u043c\u044e\u043d\u0438\u043a\u0435.\u000d\u000a\u0420\u043e\u0441\u0441\u0438\u044f \u0438 \u041a\u0438\u0442\u0430\u0439 \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u043b\u0438\u0441\u044c \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u0442\u044c \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u000d\u000a\u0432\u00a0\u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0438 \u043f\u043e\u043b\u044f\u0440\u043d\u044b\u0445 \u0441\u0443\u0434\u043e\u0432 \u0438 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0439. \u0421\u0442\u043e\u0440\u043e\u043d\u044b \u0431\u0443\u0434\u0443\u0442 \u000d\u000a\u0433\u043e\u0442\u043e\u0432\u0438\u0442\u044c \u043a\u0430\u0434\u0440\u044b, \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0432\u0430\u0442\u044c \u043e\u0431\u044a\u0435\u043c\u044b \u043f\u0435\u0440\u0435\u0432\u043e\u0437\u043e\u043a \u000d\u000a\u043f\u043e\u00a0\u0421\u0435\u0432\u043c\u043e\u0440\u043f\u0443\u0442\u0438 \u0438 \u0443\u0441\u0438\u043b\u0438\u0432\u0430\u0442\u044c \u0435\u0433\u043e \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u043e\u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u044c. \u000d\u000a\u041c\u043e\u0441\u043a\u0432\u0430 \u0438 \u041f\u0435\u043a\u0438\u043d \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u044b \u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u000d\u000a\u043d\u0430\u00a0\u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u0445 \u043f\u043b\u043e\u0449\u0430\u0434\u043a\u0430\u0445, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0410\u0440\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u000d\u000a\u0441\u043e\u0432\u0435\u0442.\u000d\u000a\u041f\u0440\u0435\u043c\u044c\u0435\u0440 \u0420\u0424 \u041c\u0438\u0445\u0430\u0438\u043b \u041c\u0438\u0448\u0443\u0441\u0442\u0438\u043d \u043f\u043e\u0441\u0435\u0442\u0438\u043b \u041a\u0438\u0442\u0430\u0439 3 4 \u043d\u043e\u044f\u0431\u0440\u044f. \u000d\u000a\u0412 \u0425\u0430\u043d\u0447\u0436\u043e\u0443 \u043e\u043d \u043f\u0440\u043e\u0432\u0435\u043b 30 \u044e \u0432\u0441\u0442\u0440\u0435\u0447\u0443 \u0433\u043b\u0430\u0432 \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432 \u000d\u000a\u0441\u00a0\u043f\u0440\u0435\u043c\u044c\u0435\u0440\u043e\u043c \u0413\u043e\u0441\u0441\u043e\u0432\u0435\u0442\u0430 \u041a\u041d\u0420 \u041b\u0438 \u0426\u044f\u043d\u043e\u043c, \u0430 \u0432 \u041f\u0435\u043a\u0438\u043d\u0435 \u000d\u000a\u0432\u0441\u0442\u0440\u0435\u0442\u0438\u043b\u0441\u044f \u0441 \u043f\u0440\u0435\u0434\u0441\u0435\u0434\u0430\u0442\u0435\u043b\u0435\u043c \u0421\u0438 \u0426\u0437\u0438\u043d\u044c\u043f\u0438\u043d\u043e\u043c, \u043e\u0431\u0441\u0443\u0434\u0438\u0432 \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0438 \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u044b\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b.\u000d\u000a08 08"]